// server/src/db.ts
import "dotenv/config";
import mysql from "mysql2/promise";
function dbConfig() {
  return {
    host: process.env.DB_HOST || "localhost",
    port: Number(process.env.DB_PORT || 3306),
    user: process.env.DB_USER || process.env.DB_USERNAME || "root",
    password: process.env.DB_PASSWORD ?? process.env.DB_PASS ?? "",
    database: process.env.DB_NAME || process.env.DB_DATABASE || "amanat_platform",
    charset: "utf8mb4",
    waitForConnections: true,
    connectionLimit: Number(process.env.DB_POOL_LIMIT || 10),
    // JSON columns come back already parsed; keep decimals as JS numbers.
    decimalNumbers: true
  };
}
var pool = null;
function getPool() {
  if (!pool) {
    pool = mysql.createPool(dbConfig());
  }
  return pool;
}
async function closePool() {
  if (pool) {
    await pool.end();
    pool = null;
  }
}

// server/src/repo.ts
async function replaceCollection(def, items) {
  const pool2 = getPool();
  const conn = await pool2.getConnection();
  try {
    await conn.beginTransaction();
    await conn.query(`DELETE FROM \`${def.table}\``);
    if (Array.isArray(items) && items.length > 0) {
      const cols = ["id", ...def.index.map((i) => i.col), "data"];
      const colList = cols.map((c) => `\`${c}\``).join(", ");
      const CHUNK = 200;
      for (let start = 0; start < items.length; start += CHUNK) {
        const slice = items.slice(start, start + CHUNK);
        const placeholders = slice.map(() => `(${cols.map(() => "?").join(", ")})`).join(", ");
        const values = [];
        for (const o of slice) {
          values.push(o.id, ...def.index.map((i) => i.get(o)), JSON.stringify(o));
        }
        await conn.query(
          `INSERT INTO \`${def.table}\` (${colList}) VALUES ${placeholders}`,
          values
        );
      }
    }
    await conn.commit();
  } catch (err) {
    await conn.rollback();
    throw err;
  } finally {
    conn.release();
  }
}
async function setSingleton(name, data, exec) {
  const runner = exec ?? getPool();
  await runner.query(
    `INSERT INTO app_singletons (name, data) VALUES (?, ?)
     ON DUPLICATE KEY UPDATE data = VALUES(data)`,
    [name, JSON.stringify(data ?? null)]
  );
}

// server/src/seed.ts
var BRAND_DEFAULTS = ["Gree", "Konka", "Haiko", "Haier", "Singer", "Samsung", "Walton", "LG", "Vision", "Chigo"];
var CATEGORY_DEFAULTS = ["Inverter AC", "Smart LED TV", "Refrigerator", "Washing Machine", "Deep Fridge", "Microwave Oven", "Home Appliance"];
var EXPENSE_CATEGORY_DEFAULTS = ["Shop Rent", "Electricity & Utility", "Staff Salary & Allowance", "Transport & Freight", "Entertainment & Tea", "Marketing & Promo", "Repair & Maintenance", "Legal & License", "Office Supplies", "Other"];
var CRM_GROUP_DEFAULTS = ["General", "VIP Club", "Wholesale Buyers", "Installment EMI Clients", "Website Leads", "Corporate", "Inactive"];
var CRM_LEAD_SOURCE_DEFAULTS = ["Showroom Walk-in", "Website Inquiry", "Facebook Campaign", "Phone Call", "Referral", "Agent Network"];
var uniq = (arr) => Array.from(new Set(arr.filter(Boolean)));
var SEED_COLLECTIONS = {
  staffUsers: INITIAL_STAFF_USERS,
  products: INITIAL_PRODUCTS,
  customers: INITIAL_CUSTOMERS,
  suppliers: INITIAL_SUPPLIERS,
  sales: INITIAL_SALES,
  installmentPlans: INITIAL_INSTALLMENT_PLANS,
  quotations: INITIAL_QUOTATIONS,
  supplierRequisitions: INITIAL_SUPPLIER_REQUISITIONS,
  purchaseOrders: INITIAL_PURCHASE_ORDERS,
  expenses: INITIAL_EXPENSES,
  smsLogs: INITIAL_SMS_LOGS,
  stockAdjustments: [],
  damageLogs: [],
  supplierReturns: [],
  customerReturns: []
};
async function seed() {
  for (const [key, items] of Object.entries(SEED_COLLECTIONS)) {
    const def = COLLECTION_BY_KEY[key];
    if (!def) throw new Error(`Unknown collection key in seed: ${key}`);
    await replaceCollection(def, items);
    console.log(`\u2713 ${key.padEnd(22)} ${items.length} row(s)`);
  }
  await setSingleton("settings", INITIAL_APP_SETTINGS);
  await setSingleton("auditConfig", INITIAL_AUDIT_CONFIG);
  console.log("\u2713 settings + auditConfig");
  const brands = uniq([...BRAND_DEFAULTS, ...INITIAL_PRODUCTS.map((p) => p.brand)]);
  const categories = uniq([...CATEGORY_DEFAULTS, ...INITIAL_PRODUCTS.map((p) => p.category)]);
  await setSingleton("brands", brands);
  await setSingleton("categories", categories);
  await setSingleton("expenseCategories", EXPENSE_CATEGORY_DEFAULTS);
  await setSingleton("crmGroups", CRM_GROUP_DEFAULTS);
  await setSingleton("crmLeadSources", CRM_LEAD_SOURCE_DEFAULTS);
  console.log(`\u2713 master lists (${brands.length} brands, ${categories.length} categories)`);
}
seed().then(async () => {
  await closePool();
  console.log("\nSeed complete. Database now mirrors src/data/initialData.ts.");
  process.exit(0);
}).catch(async (err) => {
  await closePool();
  console.error("Seed failed:", err);
  process.exit(1);
});
